-- pelicula: trailer_url = tráiler oficial en YouTube (NULL si aún no se publica); poster_url = imagen en resources/ucsur/pe/posters (51 filas)
INSERT INTO pelicula (id_pelicula, titulo, sinopsis, duracion_min, clasificacion_edad, trailer_url, poster_url, fecha_estreno, estado) VALUES
(1, 'Spider-Man: Un Nuevo Día', 'Tras borrar su identidad de la memoria de todos, Peter Parker vive solo para ser Spider-Man en las calles de Nueva York. Cuando una ola de crímenes cada vez más peligrosa lo arrastra a cruzarse con viejos y nuevos enemigos, Peter tendrá que decidir qué lugar le queda a su propia vida.', 145, '+14', 'https://www.youtube.com/watch?v=8TZMtslA3UY', 'posters/spider-man-un-nuevo-dia.jpg', '2026-07-31', 'EN_CARTELERA'),
(2, 'Hechizo de Amor 2', 'Años después de la primera película, las hermanas Sally y Gillian Owens vuelven a unir su magia cuando la maldición que persigue a los hombres de su familia amenaza a una nueva generación. Entre hechizos, secretos y amores imposibles, deberán aceptar quiénes son para proteger a las suyas.', 115, '+14', 'https://www.youtube.com/watch?v=HB9DsydGyeg', 'posters/hechizo-de-amor-2.jpg', '2026-09-11', 'EN_CARTELERA'),
(3, 'El Levantamiento', 'Inglaterra, 1381. Agobiados por los impuestos y los abusos de la corona, un humilde labrador y otros campesinos se levantan contra el joven rey Ricardo II. Lo que empieza como una protesta se convierte en una rebelión que marcha sobre Londres y sacude al reino entero.', 135, '+14', 'https://www.youtube.com/watch?v=W2VkP5Dzd0U', 'posters/el-levantamiento.jpg', '2026-09-11', 'EN_CARTELERA'),
(4, 'Fall 2: Punto Muerto', 'Tras la muerte de su hermana Shiloh, Jax acepta escalar con Luce, la mejor amiga de Shiloh, una pared de roca en Tailandia para honrar su memoria. Un error las deja atrapadas a cientos de metros de altura, sin señal y sin salida, donde cada movimiento puede ser el último.', 100, '+14', 'https://www.youtube.com/watch?v=7on5LVGhCh8', 'posters/fall-2-punto-muerto.jpg', '2026-09-04', 'EN_CARTELERA'),
(5, 'Onslaught', 'En pleno desierto, un escuadrón de supersoldados creados genéticamente escapa del control militar y deja un rastro de muerte. Una francotiradora del ejército tendrá que enfrentarse sola a esas máquinas de matar para proteger a su pequeña hija.', 105, '+18', 'https://www.youtube.com/watch?v=AMLCbpM1fRQ', 'posters/onslaught.jpg', '2026-09-04', 'EN_CARTELERA'),
(6, 'Por Cualquier Medio', 'Mississippi, década de 1960. Un joven agente negro del FBI es enviado a investigar una serie de asesinatos contra líderes de los derechos civiles. Para llegar a los responsables, el FBI lo obliga a trabajar con un sicario de la mafia, en una alianza incómoda basada en hechos reales.', 110, '+14', 'https://www.youtube.com/watch?v=S9mToIovAck', 'posters/por-cualquier-medio.jpg', '2026-09-04', 'EN_CARTELERA'),
(7, 'Resident Evil', 'Un repartidor de suministros médicos llega a Raccoon City la misma noche en que un brote convierte a sus habitantes en criaturas sedientas de sangre. Atrapado en la ciudad, tendrá que sobrevivir hasta el amanecer mientras descubre qué hay detrás de la catástrofe.', 110, '+18', 'https://www.youtube.com/watch?v=mNd1gb19A-c', 'posters/resident-evil.jpg', '2026-09-18', 'EN_CARTELERA'),
(8, 'Shaun el Cordero: La Bestia de Mossy Bottom', 'En la granja Mossy Bottom corre el rumor de que una bestia misteriosa ronda el bosque. Shaun y su rebaño deciden investigar por su cuenta y desatan una cadena de malentendidos, persecuciones y travesuras que pone de cabeza a todo el pueblo.', 90, 'APT', 'https://www.youtube.com/watch?v=UZ46Smi6mOw', 'posters/shaun-el-cordero-la-bestia-de-mossy-bottom.jpg', '2026-09-25', 'EN_CARTELERA'),
(9, 'Primetime', 'En 2006, el periodista Chris Hansen convierte las trampas televisadas a depredadores sexuales en un éxito de audiencia de la cadena NBC. Mientras el programa crece, la búsqueda del rating y del espectáculo empieza a borrar la línea entre la justicia y el morbo.', 100, '+14', 'https://www.youtube.com/watch?v=5fHXyqQOKL8', 'posters/primetime.jpg', '2026-09-25', 'EN_CARTELERA'),
(10, 'Verity', 'Lowen Ashleigh, una escritora sin dinero, es contratada por Jeremy Crawford para terminar la saga de su esposa Verity, una autora famosa que quedó incapacitada tras un accidente. En la casa de la familia, Lowen encuentra una autobiografía inédita con confesiones escalofriantes que podrían cambiarlo todo.', 115, '+14', 'https://www.youtube.com/watch?v=xdPMKhjMSFs', 'posters/verity.jpg', '2026-10-02', 'EN_CARTELERA'),
(11, 'Other Mommy', 'Bela, una niña solitaria, empieza a pasar tiempo con una presencia en su casa que tiene el mismo rostro que su madre. Esa otra mamá parece cariñosa y perfecta, pero cada día pide más, y la familia descubre demasiado tarde lo que realmente quiere.', 100, '+14', 'https://www.youtube.com/watch?v=pPxrX9ukWBY', 'posters/other-mommy.jpg', '2026-10-09', 'EN_CARTELERA'),
(12, 'Los Inocentes', 'Inspirada libremente en los cuentos de Oswaldo Reynoso, sigue a un grupo de adolescentes de un barrio de Lima en los años sesenta. Entre la violencia de la calle, el deseo y la búsqueda de identidad, Cara de Ángel y sus amigos atraviesan una noche que les cambiará la vida.', 105, '+14', 'https://www.youtube.com/watch?v=mlDSpoynZWg', 'posters/los-inocentes.jpg', '2026-10-15', 'EN_CARTELERA'),
(13, 'El Heladero: Dulce Sabor a Muerte', 'En un tranquilo pueblo veraniego, la llegada de un nuevo heladero alegra a los niños hasta que sus dulces empiezan a desatar el caos. Mientras los adultos no ven lo que pasa, tres chicos son los únicos que pueden detener la pesadilla.', 95, '+18', 'https://www.youtube.com/watch?v=4L72C7tViKE', 'posters/el-heladero-dulce-sabor-a-muerte.jpg', '2026-10-22', 'EN_CARTELERA'),
(14, 'Clayface', 'Matt Hagen, un actor de Gotham, queda desfigurado tras un ataque de la mafia. Desesperado por recuperar su rostro, se somete a un tratamiento experimental que convierte su cuerpo en una masa de arcilla capaz de adoptar cualquier forma, y que poco a poco lo transforma en un monstruo.', 115, '+14', 'https://www.youtube.com/watch?v=OGO4Mqvo3jI', 'posters/clayface.jpg', '2026-10-23', 'EN_CARTELERA'),
(15, 'Godzilla Minus Zero', 'Japón apenas se recupera de la devastación de la posguerra cuando Godzilla vuelve a aparecer, más poderoso que nunca. Koichi Shikishima y los sobrevivientes deberán unirse otra vez para enfrentar una amenaza que podría ser aún mayor que el propio rey de los monstruos.', 125, '+14', 'https://www.youtube.com/watch?v=Xmy-Z3dHMd8', 'posters/godzilla-minus-zero.jpg', '2026-11-05', 'EN_CARTELERA'),
(16, 'Digger', 'Digger Rockwell, un magnate petrolero tan carismático como imprudente, desata sin querer una catástrofe de proporciones mundiales. Mientras intenta salvar el planeta y su propia imagen al mismo tiempo, se convierte en el hombre más odiado y a la vez más necesario de la Tierra.', 129, '+14', 'https://www.youtube.com/watch?v=xQ_iyOUZcKs', 'posters/digger.jpg', '2026-10-02', 'EN_CARTELERA'),
(17, 'El Gato con Sombrero', 'En un día en que todo parece salir mal, dos hermanos reciben la visita del Gato con Sombrero, un torbellino de rimas y travesuras dispuesto a devolverles la alegría. El problema es que su ayuda siempre viene acompañada de un caos cada vez más difícil de controlar.', 108, 'APT', 'https://www.youtube.com/watch?v=HT5JAp5z0-o', 'posters/el-gato-con-sombrero.jpg', '2026-11-06', 'EN_CARTELERA'),
(18, 'La Gran Sangre: Ojo x Ojo', 'Casi veinte años después, El Dragón, Tony Blades y Mandril vuelven a reunirse para enfrentar a una mafia que controla parte del Rímac con extorsión y violencia. En una Lima más peligrosa que nunca, el trío tendrá que arreglar viejas cuentas para hacer justicia por su cuenta.', 110, '+14', 'https://www.youtube.com/watch?v=qa3ozzm4rw4', 'posters/la-gran-sangre-ojo-x-ojo.jpg', '2026-11-12', 'EN_CARTELERA'),
(19, 'Hijos de Sangre y Hueso', 'En el reino de Orïsha, la magia desapareció el día en que un rey cruel mandó exterminar a los magos. Zélie, una joven que perdió a su madre esa noche, emprende junto a su hermano y a una princesa fugitiva un viaje para devolver la magia a su pueblo, perseguida por el príncipe heredero.', 146, '+14', 'https://www.youtube.com/watch?v=a20LtkPALYM', 'posters/hijos-de-sangre-y-hueso.jpg', '2027-01-15', 'PREESTRENO'),
(20, 'Coquito: La Película', 'Arequipa, década de 1950. Everardo Zapata Santillana, un maestro recién titulado, se enfrenta a aulas donde muchos niños no logran aprender a leer. Su empeño por encontrar un método sencillo lo llevará a crear el libro Coquito, con el que aprenderían generaciones de peruanos.', 90, 'APT', 'https://www.youtube.com/watch?v=HnEaosk9Ktw', 'posters/coquito-la-pelicula.jpg', '2026-11-26', 'PREESTRENO'),
(21, 'Los Juegos del Hambre: Amanecer en la Cosecha', 'Veinticuatro años antes de Katniss, el Capitolio celebra el segundo Vasallaje de los 25 con el doble de tributos. Entre ellos está Haymitch Abernathy, un joven del Distrito 12 que tendrá que sobrevivir a una arena despiadada y desafiar a quienes controlan los Juegos.', 140, '+14', 'https://www.youtube.com/watch?v=CINFIAohu4U', 'posters/los-juegos-del-hambre-amanecer-en-la-cosecha.jpg', '2026-11-19', 'PREESTRENO'),
(22, 'Yo Soy Rocky', 'En los años setenta, un joven actor sin dinero llamado Sylvester Stallone escribe el guion de Rocky y se niega a venderlo si no lo dejan protagonizarlo. La historia real de cómo apostó todo por esa película y de cómo el desconocido de Filadelfia llegó a la cima.', 115, '+14', 'https://www.youtube.com/watch?v=V_g_Ut0jO-0', 'posters/yo-soy-rocky.jpg', '2026-11-19', 'PREESTRENO'),
(23, 'Hechizo: Bienvenidos a Hexe', 'Billie es una adolescente impulsiva que siempre se ha sentido diferente. Cuando descubre que tiene poderes mágicos, viaja a Hexe, un reino oculto de brujas, donde tendrá que aprender a controlar su magia y enfrentar un peligro que amenaza a los dos mundos.', 100, 'APT', 'https://www.youtube.com/watch?v=SVirX5zqK7s', 'posters/hechizo-bienvenidos-a-hexe.jpg', '2026-11-26', 'PREESTRENO'),
(24, 'Avengers: Doomsday', 'El Doctor Doom se alza como una amenaza capaz de destruir el multiverso entero. Los Vengadores, junto a héroes de otros mundos como los Cuatro Fantásticos y los X-Men, deberán unir fuerzas en una batalla en la que no todos saldrán con vida.', 180, '+14', 'https://www.youtube.com/watch?v=4jVs_LB2BHg', 'posters/avengers-doomsday.jpg', '2026-12-17', 'PREESTRENO'),
(25, 'Rocky', 'Rocky Balboa es un boxeador de poca monta que sobrevive en los barrios de Filadelfia cobrando deudas. Cuando el campeón mundial Apollo Creed lo elige como rival para una pelea de exhibición, Rocky ve la oportunidad de demostrar que no es un perdedor.', 120, '+14', 'https://www.youtube.com/watch?v=-Hk-LYcavrw', 'posters/rocky.jpg', '1976-11-21', 'REESTRENO'),
(26, 'Akira', 'Neo-Tokio, 2019, años después de una explosión que destruyó la ciudad. Kaneda lidera una pandilla de motociclistas hasta que su amigo Tetsuo es capturado por el gobierno y despierta unos poderes psíquicos que no puede controlar y que amenazan con arrasarlo todo.', 124, '+14', 'https://www.youtube.com/watch?v=mIuBGdeNxvQ', 'posters/akira.jpg', '1988-07-16', 'REESTRENO'),
(27, 'La Princesa Mononoke', 'Herido por un dios demonio, el joven príncipe Ashitaka viaja al oeste en busca de una cura. Allí queda atrapado en la guerra entre la Ciudad del Hierro de Lady Eboshi y los dioses del bosque, protegidos por San, una joven criada por lobos.', 134, '+14', 'https://www.youtube.com/watch?v=opCxPAwdB6U', 'posters/la-princesa-mononoke.jpg', '1997-07-12', 'REESTRENO'),
(28, 'Una Mente Brillante', 'John Nash, un brillante matemático de Princeton, revoluciona la economía con sus ideas mientras su mente empieza a traicionarlo. Con el apoyo de su esposa, deberá luchar contra la esquizofrenia para no perder su vida, su familia y su obra.', 135, '+14', 'https://www.youtube.com/watch?v=YWwAOutgWBQ', 'posters/una-mente-brillante.jpg', '2001-12-21', 'REESTRENO'),
(29, 'Avengers: Endgame', 'Tras el chasquido de Thanos que borró a la mitad del universo, los Vengadores que quedan viven entre la culpa y la derrota. Una posibilidad inesperada los lleva a viajar en el tiempo para reunir las Gemas del Infinito y revertir lo ocurrido, cueste lo que cueste.', 181, '+14', 'https://www.youtube.com/watch?v=TcMBFSGVi1c', 'posters/avengers-endgame.jpg', '2019-04-25', 'REESTRENO'),
(30, 'La Nueva Focker', 'Henry Focker, hijo de Greg y Pam, está listo para casarse con Olivia, una joven decidida que quiere ganarse a la familia. Ahora es Greg quien desconfía de la futura nuera, y con Jack Byrnes de vuelta, el círculo de confianza vuelve a ponerse a prueba.', 105, '+14', 'https://www.youtube.com/watch?v=KunVOtpGLog', 'posters/la-nueva-focker.jpg', '2026-11-26', 'PROXIMAMENTE'),
(31, 'Noche de Paz 2', 'Santa Claus termina en la lista de los traviesos y pierde sus poderes justo antes de Navidad. Cuando un mafioso toma un centro comercial lleno de rehenes, Santa tendrá que enfrentarlo a puño limpio, esta vez con la ayuda de la señora Claus.', 110, '+18', 'https://www.youtube.com/watch?v=4COPTWV5Fn8', 'posters/noche-de-paz-2.jpg', '2026-12-04', 'PROXIMAMENTE'),
(32, 'Dune: Parte Tres', 'Años después de convertirse en emperador, Paul Atreides gobierna un imperio en el que una guerra santa se libra en su nombre. Mientras las conspiraciones crecen a su alrededor, Paul deberá enfrentar el precio de las visiones del futuro que lo llevaron al poder.', 165, '+14', 'https://www.youtube.com/watch?v=NdvqHc56lE0', 'posters/dune-parte-tres.jpg', '2026-12-18', 'PROXIMAMENTE'),
(33, 'Angry Birds 3', 'Red, Chuck, Bomb y el resto de las aves vuelven a la acción cuando una nueva amenaza pone en peligro la Isla de las Aves. Para salvar su hogar tendrán que trabajar en equipo, incluso con los cerdos, en su aventura más alocada.', 95, 'APT', 'https://www.youtube.com/watch?v=a9DB_aUMzME', 'posters/angry-birds-3.jpg', '2026-12-23', 'PROXIMAMENTE'),
(34, 'Jumanji: Mundo Abierto', 'Spencer, Martha, Fridge y Bethany regresan a Jumanji, pero esta vez el juego se ha convertido en un mundo abierto sin reglas claras. Con sus avatares de siempre y nuevos peligros a cada paso, deberán llegar al final de una partida en la que todo puede salirse de control.', 120, 'APT', 'https://www.youtube.com/watch?v=6O8MxphAFIQ', 'posters/jumanji-mundo-abierto.jpg', '2026-12-25', 'PROXIMAMENTE'),
(35, 'Narnia: El Sobrino del Mago', 'Londres, 1900. Digory y Polly encuentran unos anillos mágicos creados por el tío de Digory que los transportan entre mundos. Su viaje los lleva a despertar a la temible Jadis y a presenciar el nacimiento de Narnia, creada por el canto del león Aslan.', 130, 'APT', 'https://www.youtube.com/watch?v=gDJ-ini7fF0', 'posters/narnia-el-sobrino-del-mago.jpg', '2027-02-12', 'PROXIMAMENTE'),
(36, 'Gatto', 'En una Venecia llena de supersticiones, un gato negro que sobrevive entre canales y callejones se mete en problemas con una banda de gatos mafiosos. Para salir del lío tendrá que aliarse con quien menos espera y descubrir que la mala suerte no siempre es lo que parece.', 100, 'APT', 'https://www.youtube.com/watch?v=NIKfR_uF_d0', 'posters/gatto.jpg', '2027-03-05', 'PROXIMAMENTE'),
(37, 'Shrek 5', 'Shrek, Fiona y sus hijos ya crecieron, y la vida en el pantano no es tan tranquila como parecía. Una nueva aventura obliga a la familia, con Burro y el Gato con Botas, a salir de nuevo al mundo de los cuentos de hadas.', 95, 'APT', 'https://www.youtube.com/watch?v=736n3sotmeE', 'posters/shrek-5.jpg', '2027-06-30', 'PROXIMAMENTE'),
(38, 'CoComelon: La Película', 'JJ y sus amigos están por empezar el jardín de niños, y ese gran paso los lleva a salir por primera vez a un mundo mucho más grande que su barrio. Una aventura musical llena de canciones, nuevos amigos y lecciones sobre crecer.', 90, 'APT', 'https://www.youtube.com/watch?v=JciwN7x6mB8', 'posters/cocomelon-la-pelicula.jpg', '2027-02-19', 'PROXIMAMENTE'),
(39, 'El Caso Thomas Crown', 'Thomas Crown es un millonario que lo tiene todo y que, por puro aburrimiento, planea el robo de una obra de arte de valor incalculable. La investigadora encargada del caso sospecha de él desde el principio, y entre ambos empieza un juego de seducción en el que ninguno quiere perder.', 130, '+14', 'https://www.youtube.com/watch?v=gnm4HgIAVmU', 'posters/el-caso-thomas-crown.jpg', '2027-03-05', 'PROXIMAMENTE'),
(40, 'Lords of War', 'Yuri Orlov, el traficante de armas más famoso del mundo, vuelve al negocio cuando un mercenario despiadado decide destruir todo el mercado ilegal de armas. Para sobrevivir, Yuri tendrá que enfrentarse a alguien tan frío y calculador como él.', 120, '+18', 'https://www.youtube.com/watch?v=FLMGNKxJrDk', 'posters/lords-of-war.jpg', '2027-01-22', 'PROXIMAMENTE'),
(41, 'Super Mario Galaxy: La Película', 'Mario y Luigi dejan el Reino Champiñón para viajar por el espacio, donde conocen a Estela, la protectora de las galaxias. Juntos deberán detener a Bowser Jr., que busca vengar a su padre y apoderarse del cosmos.', 100, 'APT', 'https://www.youtube.com/watch?v=FdL2GorGdKc', 'posters/super-mario-galaxy-la-pelicula.jpg', '2026-04-02', 'FUERA_DE_CARTELERA'),
(42, 'Proyecto Fin del Mundo', 'Ryland Grace despierta solo en una nave espacial, sin recordar quién es ni cómo llegó allí. Poco a poco descubre que es la última esperanza de la humanidad para salvar al Sol de un microorganismo que lo está apagando, y que no es el único ser vivo en esa misión.', 155, '+14', 'https://www.youtube.com/watch?v=_m8Ts9hhk-8', 'posters/proyecto-fin-del-mundo.jpg', '2026-03-20', 'FUERA_DE_CARTELERA'),
(43, 'Michael', 'La vida de Michael Jackson desde su infancia en los Jackson 5, bajo la dura disciplina de su padre, hasta convertirse en el Rey del Pop. Un retrato del artista detrás de las canciones, los escenarios y la fama que cambió la música para siempre.', 125, '+14', 'https://www.youtube.com/watch?v=mbtgEE6rkxw', 'posters/michael.jpg', '2026-04-24', 'FUERA_DE_CARTELERA'),
(44, 'El Diablo Viste a la Moda 2', 'Casi veinte años después, Miranda Priestly lucha por mantener a flote la revista Runway en plena caída de los medios impresos. Su camino se cruza otra vez con Andy Sachs y con Emily, ahora ejecutiva de una marca de lujo que tiene el dinero que Miranda necesita.', 120, '+14', 'https://www.youtube.com/watch?v=gFJIo2aoP24', 'posters/el-diablo-viste-a-la-moda-2.jpg', '2026-05-01', 'FUERA_DE_CARTELERA'),
(45, 'Toy Story 5', 'Los juguetes de siempre enfrentan un rival inesperado: la tecnología. Cuando Lilypad, una tableta inteligente, se convierte en la favorita de los niños, Woody, Buzz y sus amigos tendrán que demostrar que el juego de verdad sigue valiendo la pena.', 100, 'APT', 'https://www.youtube.com/watch?v=c51ND9Hdbw0', 'posters/toy-story-5.jpg', '2026-06-19', 'FUERA_DE_CARTELERA'),
(46, 'La Odisea', 'Tras la guerra de Troya, el rey Odiseo emprende el largo viaje de regreso a Ítaca, donde lo esperan su esposa Penélope y su hijo Telémaco. Durante años deberá enfrentar dioses, monstruos y tentaciones que pondrán a prueba su astucia y su voluntad de volver a casa.', 170, '+14', 'https://www.youtube.com/watch?v=Mzw2ttJD2qQ', 'posters/la-odisea.jpg', '2026-07-17', 'FUERA_DE_CARTELERA'),
(47, 'El Viaje de Chihiro', 'Durante una mudanza, Chihiro, una niña de diez años, entra con sus padres a un mundo de espíritus donde ellos quedan convertidos en cerdos. Para salvarlos, tendrá que trabajar en la casa de baños de la bruja Yubaba y encontrar el valor que no sabía que tenía.', 125, 'APT', 'https://www.youtube.com/watch?v=GAp2_0JJskk', 'posters/el-viaje-de-chihiro.jpg', '2001-07-20', 'REESTRENO'),
(48, 'Tu Nombre', 'Mitsuha, una joven de un pueblo de montaña, y Taki, un estudiante de Tokio, empiezan a despertar de vez en cuando en el cuerpo del otro. Mientras aprenden a convivir con ese extraño vínculo, descubren que el destino de los dos está unido a un cometa que se acerca a la Tierra.', 106, 'APT', 'https://www.youtube.com/watch?v=RuyHIkXdYf8', 'posters/tu-nombre.jpg', '2016-08-26', 'REESTRENO'),
(49, 'Mi Vecino Totoro', 'Satsuki y su hermana menor Mei se mudan al campo con su padre para estar cerca del hospital donde se recupera su madre. En el bosque que rodea su nueva casa descubren a Totoro, un gran espíritu que las acompaña en una aventura tan sencilla como mágica.', 86, 'APT', 'https://www.youtube.com/watch?v=HaLISMAGdOE', 'posters/mi-vecino-totoro.jpg', '1988-04-16', 'REESTRENO'),
(50, 'Demon Slayer: Castillo Infinito', 'Tanjiro Kamado y los Pilares del Cuerpo de Exterminio de Demonios son arrastrados al Castillo Infinito, la fortaleza de Muzan Kibutsuji. En sus pasillos imposibles comienza la batalla final contra las Lunas Superiores, donde cada combate puede ser el último.', 156, '+14', 'https://www.youtube.com/watch?v=wyiZWYMilgk', 'posters/demon-slayer-castillo-infinito.jpg', '2025-09-11', 'FUERA_DE_CARTELERA'),
(51, 'Chainsaw Man – La Película: Arco de Reze', 'Denji, el cazador de demonios que puede convertirse en Chainsaw Man, conoce a Reze, una chica encantadora que trabaja en una cafetería. Por primera vez siente que tiene una vida normal, pero Reze esconde un secreto explosivo que lo pondrá frente a su enemigo más peligroso.', 100, '+18', 'https://www.youtube.com/watch?v=3fcr6jyiQY0', 'posters/chainsaw-man-arco-de-reze.jpg', '2025-10-24', 'FUERA_DE_CARTELERA');

