-- butaca de las salas 46 a 84 (se generan aquí con SQL). Distribución por formato (filas, laterales por lado, centrales):
--    2D y 3D 10x(3+8+3) = 140 · Prime 7x(2+6+2) = 70 · 4DX 8x(2+6+2) = 80 · IMAX 14x(4+10+4) = 252
--    VIP Gold 5x(2+6+2) = 50 · VIP Platinum 4x(2+4+2) = 32 · ScreenX 12x(3+9+3) = 180
--    DISCAPACIDAD junto a los pasillos en la primera fila (y en la última si hay 6 filas o más);
--    PREFERENCIAL en la mitad central del bloque CENTRO, a una fila o menos de la fila ideal (2/3 del fondo).
INSERT INTO butaca (fila, numero, tipo, bloque, id_sala)
WITH RECURSIVE nums (n) AS (
    SELECT 1 UNION ALL SELECT n + 1 FROM nums WHERE n < 30
),
dist (id_tipo_sala, filas, lat, cen) AS (
    SELECT 1, 10, 3, 8 UNION ALL SELECT 2, 10, 3, 8 UNION ALL SELECT 3, 7, 2, 6
    UNION ALL SELECT 4, 7, 2, 6 UNION ALL SELECT 5, 8, 2, 6 UNION ALL SELECT 6, 14, 4, 10
    UNION ALL SELECT 7, 5, 2, 6 UNION ALL SELECT 8, 4, 2, 4 UNION ALL SELECT 9, 12, 3, 9
),
s AS (
    SELECT sa.id_sala, d.filas, d.lat, d.cen, 2 * d.lat + d.cen AS por_fila,
           ROUND((d.filas - 1) * 2 / 3) AS ideal
      FROM sala sa JOIN dist d ON d.id_tipo_sala = sa.id_tipo_sala
     WHERE sa.id_sala BETWEEN 46 AND 84
)
SELECT CHAR(64 + f.n),
       b.n,
       CASE WHEN (f.n = 1 OR (f.n = s.filas AND s.filas >= 6))
                 AND (b.n = s.lat OR b.n = s.lat + s.cen + 1) THEN 'DISCAPACIDAD'
            WHEN b.n > s.lat AND b.n <= s.lat + s.cen
                 AND ABS((f.n - 1) - s.ideal) <= 1
                 AND (b.n - s.lat) > s.cen DIV 4
                 AND (b.n - s.lat) <= s.cen - s.cen DIV 4 THEN 'PREFERENCIAL'
            ELSE 'ESTANDAR' END,
       CASE WHEN b.n <= s.lat THEN 'IZQUIERDA'
            WHEN b.n <= s.lat + s.cen THEN 'CENTRO'
            ELSE 'DERECHA' END,
       s.id_sala
  FROM s
  JOIN nums f ON f.n <= s.filas
  JOIN nums b ON b.n <= s.por_fila
 ORDER BY s.id_sala, f.n, b.n;

