-- ============================================================
-- Ajustes para que los datos cuadren con las reglas de Java
-- ============================================================

-- usos_realizados = compras CONFIRMADAS que usaron el cupon
-- (una compra REEMBOLSADA devuelve el uso, como Cupon.revertirUso en Java)
-- El WHERE por la clave permite ejecutarlo con el "safe update mode" de Workbench.
UPDATE cupon cu
   SET usos_realizados = (SELECT COUNT(*) FROM compra c
                           WHERE c.id_cupon = cu.id_cupon AND c.estado = 'CONFIRMADA')
 WHERE cu.id_cupon > 0;

-- Horarios adicionales de preestreno (3 horarios por sala en el día previo al estreno)
-- para que las películas en Preventa también ofrezcan varias opciones sin solaparse.
INSERT INTO funcion (fecha, hora_inicio, idioma, estado, id_pelicula, id_sala)
WITH t_pre (turno, hora) AS (
    SELECT 0, '13:00:00' UNION ALL SELECT 1, '17:00:00' UNION ALL SELECT 2, '21:00:00'
),
salas_pre AS (
    SELECT sa.id_sala, sa.id_sede,
           ROW_NUMBER() OVER (PARTITION BY sa.id_sede ORDER BY sa.numero) - 1 AS idx
      FROM sala sa JOIN sede se ON se.id_sede = sa.id_sede
     WHERE sa.estado = 'ACTIVA' AND se.estado = 'ACTIVA'
),
pre_futuras AS (
    SELECT p.id_pelicula, p.duracion_min, DATE_SUB(p.fecha_estreno, INTERVAL 1 DAY) AS fecha_pre,
           ROW_NUMBER() OVER (ORDER BY p.id_pelicula) - 1 AS rn
      FROM pelicula p
     WHERE p.estado = 'PREESTRENO'
       AND DATE_SUB(p.fecha_estreno, INTERVAL 1 DAY) > DATE_ADD(CURDATE(), INTERVAL 11 DAY)
)
SELECT pf.fecha_pre,
       tp.hora,
       CASE WHEN pf.id_pelicula IN (12, 13, 18, 20) THEN 'Español'
            WHEN tp.turno = 2 THEN 'Subtitulada' ELSE 'Doblada' END,
       'DISPONIBLE',
       pf.id_pelicula,
       sp.id_sala
  FROM pre_futuras pf
  JOIN salas_pre sp ON sp.idx IN ((pf.rn * 2) MOD 6, (pf.rn * 2 + 3) MOD 6)
 CROSS JOIN t_pre tp
 WHERE NOT EXISTS (
        SELECT 1
          FROM funcion f JOIN pelicula pe ON pe.id_pelicula = f.id_pelicula
         WHERE f.id_sala = sp.id_sala
           AND f.fecha = pf.fecha_pre
           AND f.estado <> 'CANCELADA'
           AND TIME_TO_SEC(f.hora_inicio) < TIME_TO_SEC(tp.hora) + (pf.duracion_min + 15) * 60
           AND TIME_TO_SEC(tp.hora) < TIME_TO_SEC(f.hora_inicio) + (pe.duracion_min + 15) * 60);

-- Horarios adicionales en las salas que ya tienen preestreno hoy/próximos días (ej. Coquito, Hechizo)
INSERT INTO funcion (fecha, hora_inicio, idioma, estado, id_pelicula, id_sala)
WITH t_extra (turno, hora) AS (
    SELECT 0, '13:30:00' UNION ALL SELECT 1, '21:00:00'
),
pre_existentes AS (
    SELECT DISTINCT f.id_pelicula, f.id_sala, f.fecha, p.duracion_min
      FROM funcion f JOIN pelicula p ON p.id_pelicula = f.id_pelicula
     WHERE p.estado = 'PREESTRENO'
       AND f.fecha BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 11 DAY)
       AND f.estado <> 'CANCELADA'
)
SELECT pe.fecha,
       te.hora,
       CASE WHEN pe.id_pelicula IN (12, 13, 18, 20) THEN 'Español'
            WHEN te.turno = 1 THEN 'Subtitulada' ELSE 'Doblada' END,
       'DISPONIBLE',
       pe.id_pelicula,
       pe.id_sala
  FROM pre_existentes pe
 CROSS JOIN t_extra te
 WHERE NOT EXISTS (
        SELECT 1
          FROM funcion f JOIN pelicula p2 ON p2.id_pelicula = f.id_pelicula
         WHERE f.id_sala = pe.id_sala
           AND f.fecha = pe.fecha
           AND f.estado <> 'CANCELADA'
           AND TIME_TO_SEC(f.hora_inicio) < TIME_TO_SEC(te.hora) + (pe.duracion_min + 15) * 60
           AND TIME_TO_SEC(te.hora) < TIME_TO_SEC(f.hora_inicio) + (p2.duracion_min + 15) * 60);

-- Funciones de los próximos 12 días (desde el día en que se ejecuta el script), así la cartelera nunca queda vacía
-- y cada película ofrece múltiples horarios en cada formato de sala.
-- Solo salas ACTIVAS de sedes ACTIVAS y películas EN_CARTELERA o REESTRENO (los preestrenos tienen las suyas, arriba).
-- Cada sede activa tiene 6 salas x 6 turnos = 36 funciones por día: 6 películas con 6 horarios cada una
-- (3 horarios en un formato y 3 horarios en otro formato distinto).
-- Las 6 películas de cada sede rotan cada día (en 12 días todas pasan 2 a 3 veces por cada sede).
-- Los turnos van cada 2 h 40 min (09:40 a 23:00): alcanzan para películas de hasta 145 min más 15 de limpieza.
-- Para películas más largas (> 145 min, en pos = 5): ocupan los turnos 0, 2 y 4 en la sala 5 (5 h 20 min entre sí)
-- y el turno 5 (23:00) en la sala 2, omitiendo los turnos impares de la sala 5 para evitar cualquier cruce.
-- Mezcla de Doblada y Subtitulada en cada formato; las peruanas se dan en Español.
-- No se programa nada que se cruce con una función que ya existe en esa sala (preestrenos, ventas hechas).
INSERT INTO funcion (fecha, hora_inicio, idioma, estado, id_pelicula, id_sala)
WITH RECURSIVE d (dia) AS (
    SELECT 0 UNION ALL SELECT dia + 1 FROM d WHERE dia < 11
),
t (turno, hora) AS (
    SELECT 0, '09:40:00' UNION ALL SELECT 1, '12:20:00' UNION ALL SELECT 2, '15:00:00'
    UNION ALL SELECT 3, '17:40:00' UNION ALL SELECT 4, '20:20:00' UNION ALL SELECT 5, '23:00:00'
),
k (pos) AS (
    SELECT 0 UNION ALL SELECT pos + 1 FROM k WHERE pos < 5
),
p AS (
    SELECT id_pelicula, duracion_min,
           ROW_NUMBER() OVER (ORDER BY id_pelicula) - 1 AS rn,
           COUNT(*) OVER ()                             AS total
      FROM pelicula
     WHERE estado IN ('EN_CARTELERA', 'REESTRENO')
),
salas AS (
    SELECT sa.id_sala, sa.id_sede,
           ROW_NUMBER() OVER (PARTITION BY sa.id_sede ORDER BY sa.numero) - 1 AS idx,
           COUNT(*) OVER (PARTITION BY sa.id_sede)                            AS n_salas
      FROM sala sa JOIN sede se ON se.id_sede = sa.id_sede
     WHERE sa.estado = 'ACTIVA' AND se.estado = 'ACTIVA'
),
elegidas AS (
    -- las largas (> 145 min) van al final (pos = 5) para no chocar con turnos adyacentes
    SELECT se.id_sede, d.dia, p.id_pelicula, p.duracion_min,
           ROW_NUMBER() OVER (PARTITION BY se.id_sede, d.dia ORDER BY p.duracion_min > 145, k.pos) - 1 AS pos,
           MAX(p.duracion_min > 145) OVER (PARTITION BY se.id_sede, d.dia) AS hay_larga
      FROM (SELECT DISTINCT id_sede FROM salas) se
     CROSS JOIN d
     CROSS JOIN k
      JOIN p ON p.rn = (se.id_sede * 7 + d.dia * 6 + k.pos) MOD p.total
),
ranuras AS (
    SELECT s.id_sala, s.id_sede, d.dia, t.turno, t.hora, s.idx,
           CASE WHEN t.turno MOD 2 = 0 THEN s.idx ELSE (s.idx + 3) MOD s.n_salas END AS pos_objetivo
      FROM salas s CROSS JOIN d CROSS JOIN t
)
SELECT DATE_ADD(CURDATE(), INTERVAL r.dia DAY),
       r.hora,
       CASE WHEN e.id_pelicula IN (12, 13, 18, 20) THEN 'Español'
            WHEN r.turno IN (3, 4, 5) THEN 'Subtitulada' ELSE 'Doblada' END,
       'DISPONIBLE',
       e.id_pelicula,
       r.id_sala
  FROM ranuras r
  JOIN elegidas e ON e.id_sede = r.id_sede AND e.dia = r.dia AND e.pos = r.pos_objetivo
 WHERE (e.duracion_min <= 145 OR (r.idx = 5 AND r.turno IN (0, 2, 4)) OR (r.idx = 2 AND r.turno = 5))
   AND NOT (e.hay_larga = 1 AND r.idx = 5 AND r.turno IN (1, 3, 5))
   AND NOT EXISTS (
        SELECT 1
          FROM funcion f JOIN pelicula pf ON pf.id_pelicula = f.id_pelicula
         WHERE f.id_sala = r.id_sala
           AND f.fecha = DATE_ADD(CURDATE(), INTERVAL r.dia DAY)
           AND f.estado <> 'CANCELADA'
           AND TIME_TO_SEC(f.hora_inicio) < TIME_TO_SEC(r.hora) + (e.duracion_min + 15) * 60
           AND TIME_TO_SEC(r.hora) < TIME_TO_SEC(f.hora_inicio) + (pf.duracion_min + 15) * 60);

-- las compras reembolsadas de prueba no tenian dulceria entregada: se les devolvio el total
UPDATE compra SET monto_reembolsado = total WHERE estado = 'REEMBOLSADA';

-- el correlativo de boletas queda en el ultimo numero usado
UPDATE correlativo SET ultimo_numero = 75 WHERE serie = 'B001';

